spec.expr:
avg by (rems_application_group, rems_service) (
  rate(container_cpu_usage_seconds_total{
    metrics_path="/metrics/cadvisor",
    container!="",
    # cluster="$cluster",
    image!="",
    pod=~"^$service.*$"

  }[1m])
  * on(pod) group_left(rems_application_group, rems_service) (
    kube_pod_labels{
      rems_application_group="$ApplicationGroup",
      rems_service="$service",
      rems_environment="$env"
    }
  )
)

max by (rems_application_group, rems_service) (
  rate(container_cpu_usage_seconds_total{
    metrics_path="/metrics/cadvisor",
    container!="",
    # cluster="$cluster",
    image!="",
    pod=~"^$service.*$"

  }[1m])
  * on(pod) group_left(rems_application_group, rems_service) (
    kube_pod_labels{
      rems_application_group="$ApplicationGroup",
      rems_service="$service",
      rems_environment="$env"
    }
  )
)

sum by (image_spec) (
  label_replace(
    kube_pod_container_info{container!="", pod=~"^$service.*"}
    * on(pod) group_left(rems_application_group, rems_service) (
      kube_pod_labels{
        rems_application_group="$ApplicationGroup",
        rems_service="$service",
        rems_environment="$env"
      }
    ),
    "image", "$1", "image", ".*/([^:]+).*"
  )
)

avg by (rems_application_group, rems_service) (
  container_memory_working_set_bytes{
    metrics_path="/metrics/cadvisor",
    container!="",
    # cluster="$cluster",
    image!="",
    pod=~"^$service.*$"
  }
  * on(pod) group_left(rems_application_group, rems_service) (
    kube_pod_labels{
      rems_application_group="$ApplicationGroup",
      rems_service="$service",
      rems_environment="$env"
    }
  )
)

max by (rems_application_group, rems_service) (
  container_memory_working_set_bytes{
    metrics_path="/metrics/cadvisor",
    container!="",
    # cluster="$cluster",
    image!="",
    pod=~"^$service.*$"
  }
  * on(pod) group_left(rems_application_group, rems_service) (
    kube_pod_labels{
      rems_application_group!="",
      rems_service!=""
    }
  )
)

sum by (image_spec) (
  label_replace(
    kube_pod_container_info{container!="", pod=~"^$service.*"}
    * on(pod) group_left(rems_application_group, rems_service) (
      kube_pod_labels{
        rems_application_group="$ApplicationGroup",
        rems_service="$service",
        rems_environment="$env"
      }
    ),
    "image", "$1", "image", ".*/([^:]+).*"
  )
)

container_memory_working_set_bytes{
  metrics_path="/metrics/cadvisor",
  container!="",
  # cluster="$cluster",
  image!="",
  pod=~"^$service.*$"
}
* on(pod) group_left(rems_application_group, rems_service)
  kube_pod_labels{      
    rems_application_group="$ApplicationGroup",
    rems_service="$service",
    rems_environment="$env" 
  }

sum(
  rate(
    container_cpu_usage_seconds_total{
      metrics_path="/metrics/cadvisor",
    #   cluster="$cluster",
      image!="",
      container!="",
      container=~"$container",
      pod=~"^$service.*$"
    }[5m]
  )
) by (pod, container)
* on(pod) group_left(
  rems_application_group,
  rems_service
)
kube_pod_labels{
  rems_application_group="$ApplicationGroup",
  rems_service="$service",
  rems_environment="$env"
}

(
    sum(
        rate(
            traces_span_metrics_duration_milliseconds_count{
                rems_application_group="$ApplicationGroup",
                rems_service="$service",
                rems_environment="$env",
                span_kind="SPAN_KIND_SERVER",
                http_status_code=~"^2.*|^3.*",
                http_route=~"$route"
            }[5m]
        ) or on() vector(0)
    )
    +
    sum(
        rate(
            traces_span_metrics_duration_milliseconds_count{
                rems_application_group="$ApplicationGroup",
                rems_service="$service",
                rems_environment="$env",
                span_kind="SPAN_KIND_SERVER",
                rpc_grpc_status_code=~"0|1",
                http_route=~"$route"
            }[5m]
        ) or on() vector(0)
    )
)
* 100
/
sum(
    rate(
        traces_span_metrics_duration_milliseconds_count{
            span_kind="SPAN_KIND_SERVER",
            rems_application_group="$ApplicationGroup",
            rems_service="$service",
            rems_environment="$env",
            http_route=~"$route"
        }[5m]
    )
)

{service_name="kube-events"} 
| k8s_object_name=~"$service.*"
| label_format event_message="{{__line__}}"
